using System;using System.Linq;using UnityEngine;using UnityEngine.AI;using UnityEditor;using UnityEditor.SceneManagement;using Unity.AI.Navigation;
public static class FinalizeCampusGeometry {
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit Mode required");var buses=GameObject.Find("Campus exterior upgrade/Campus school buses");foreach(Transform b in buses.transform){b.position=new Vector3(27.6f,b.position.y,b.position.z);foreach(var t in b.GetComponentsInChildren<TMPro.TMP_Text>())if(t.text=="SCHOOL BUS")t.gameObject.SetActive(false);}
 var surface=UnityEngine.Object.FindAnyObjectByType<NavMeshSurface>();Physics.SyncTransforms();surface.BuildNavMesh();var generated=surface.navMeshData;var saved=AssetDatabase.LoadAssetAtPath<NavMeshData>("Assets/_FireSafety/SchoolExpansion/Navigation/SchoolNavMesh.asset");EditorUtility.CopySerialized(generated,saved);surface.RemoveData();surface.navMeshData=saved;surface.AddData();UnityEngine.Object.DestroyImmediate(generated);EditorUtility.SetDirty(saved);EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();return new{triangles=NavMesh.CalculateTriangulation().indices.Length/3,agent=surface.agentTypeID};}
}
